        EventData.EventID = EventID;
        EventData.DayNum = Data.DayNum;
        EventData.SupplementDayNum = Data.SupplementDayNum;
        EventData.NextDayTime = Data.NextDayTime;

        self.SignInEventData:Add(EventData);
    end
end

